// Notification utilities
export class NotificationManager {
  private static instance: NotificationManager;
  private permission: NotificationPermission = 'default';
  private audioContext: AudioContext | null = null;
  private notificationSound: AudioBuffer | null = null;

  private constructor() {
    this.checkPermission();
    this.initializeAudio();
  }

  public static getInstance(): NotificationManager {
    if (!NotificationManager.instance) {
      NotificationManager.instance = new NotificationManager();
    }
    return NotificationManager.instance;
  }

  private checkPermission() {
    if ('Notification' in window) {
      this.permission = Notification.permission;
    }
  }

  public async requestPermission(): Promise<boolean> {
    if (!('Notification' in window)) {
      console.warn('This browser does not support notifications');
      return false;
    }

    if (this.permission === 'granted') {
      return true;
    }

    const permission = await Notification.requestPermission();
    this.permission = permission;
    return permission === 'granted';
  }

  private async initializeAudio() {
    try {
      this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      
      // Create a simple notification sound
      const buffer = this.audioContext.createBuffer(1, 44100 * 0.1, 44100);
      const data = buffer.getChannelData(0);
      
      for (let i = 0; i < data.length; i++) {
        data[i] = Math.sin(2 * Math.PI * 800 * i / 44100) * 0.3;
      }
      
      this.notificationSound = buffer;
    } catch (error) {
      console.warn('Could not initialize audio context:', error);
    }
  }

  public async playNotificationSound(volume: number = 0.5) {
    if (!this.audioContext || !this.notificationSound) {
      // Fallback to system beep
      try {
        const audio = new Audio('data:audio/wav;base64,');
        audio.volume = volume;
        audio.play().catch(() => {});
      } catch (error) {
        console.warn('Could not play notification sound:', error);
      }
      return;
    }

    try {
      const source = this.audioContext.createBufferSource();
      const gainNode = this.audioContext.createGain();
      
      source.buffer = this.notificationSound;
      gainNode.gain.value = volume;
      
      source.connect(gainNode);
      gainNode.connect(this.audioContext.destination);
      
      source.start();
    } catch (error) {
      console.warn('Could not play notification sound:', error);
    }
  }

  public async showNotification(title: string, options: NotificationOptions = {}) {
    if (this.permission !== 'granted') {
      return false;
    }

    try {
      const notification = new Notification(title, {
        icon: '/vite.svg',
        badge: '/vite.svg',
        ...options,
      });

      // Auto-close after 5 seconds
      setTimeout(() => {
        notification.close();
      }, 5000);

      return true;
    } catch (error) {
      console.warn('Could not show notification:', error);
      return false;
    }
  }

  public async notifyNewMessage(senderName: string, message: string, settings: any) {
    if (!settings.enabled) return;

    // Play sound if enabled
    if (settings.sound) {
      await this.playNotificationSound(settings.soundVolume);
    }

    // Show desktop notification if enabled
    if (settings.desktop) {
      await this.showNotification(`New message from ${senderName}`, {
        body: message.length > 50 ? message.substring(0, 50) + '...' : message,
        tag: 'new-message',
      });
    }
  }

  public async notifyMention(senderName: string, message: string, settings: any) {
    if (!settings.enabled || !settings.mentions) return;

    // Play sound if enabled
    if (settings.sound) {
      await this.playNotificationSound(settings.soundVolume);
    }

    // Show desktop notification if enabled
    if (settings.desktop) {
      await this.showNotification(`${senderName} mentioned you`, {
        body: message.length > 50 ? message.substring(0, 50) + '...' : message,
        tag: 'mention',
      });
    }
  }
}

export const notificationManager = NotificationManager.getInstance();